func activate(ctx context.Context, in <-chan Order, out chan<- Receipt, svc *OrderService) {
	for o := range in {                          // fan out: start N goroutines
		r, err := svc.Place(ctx, o)              // ordinary service call
		if err != nil {
			errors <- err                        // failure path, not a silent drop
			continue
		}
		out <- r                                 // reply
	}
}
